arguments.file_text:
@page "/chat"
@using sv_cb1cf2172c864088a29a5ec24e992db0.Services
@rendermode InteractiveServer
@inject IChatService ChatService

<PageTitle>Chat</PageTitle>

<div class="chat-layout">
    <div class="sidebar">
        <ChannelList Channels="channels"
                     SelectedChannelId="selectedChannelId"
                     OnChannelSelected="SelectChannel" />
    </div>

    <div class="main-area @(activeThreadRootId.HasValue ? "with-thread" : "full-width")">
        @if (selectedChannel is not null)
        {
            <MessageArea ChannelName="@selectedChannel.Name"
                         ChannelDescription="@selectedChannel.Description"
                         Messages="messages"
                         ThreadReplyCounts="threadReplyCounts"
                         IsLoadingMore="isLoadingMore"
                         OnSendMessage="SendMessage"
                         OnOpenThread="OpenThread"
                         OnReact="HandleReaction"
                         OnLoadMore="LoadMoreMessages" />
        }
        else
        {
            <div class="empty-state">
                <p>Select a channel to start chatting</p>
            </div>
        }
    </div>

    @if (activeThreadRootId.HasValue)
    {
        <div class="thread-pane">
            <ThreadPanel RootMessage="threadRootMessage"
                         Replies="threadReplies"
                         OnClose="CloseThread"
                         OnSendReply="SendThreadReply" />
        </div>
    }
</div>

@code {
    private const int PageSize = 30;

    private List<Channel> channels = [];
    private Channel? selectedChannel;
    private int? selectedChannelId;
    private List<Message> messages = [];
    private Dictionary<int, int> threadReplyCounts = new();

    private int? activeThreadRootId;
    private Message? threadRootMessage;
    private List<Message> threadReplies = [];

    private int messageSkip;
    private bool hasMoreMessages = true;
    private bool isLoadingMore;

    protected override async Task OnInitializedAsync()
    {
        channels = await ChatService.GetChannelsAsync();

        if (channels.Count > 0)
        {
            await SelectChannel(channels[0].Id);
        }
    }

    private async Task SelectChannel(int channelId)
    {
        selectedChannelId = channelId;
        selectedChannel = channels.FirstOrDefault(c => c.Id == channelId);
        messageSkip = 0;
        hasMoreMessages = true;
        messages = [];
        threadReplyCounts = new();
        CloseThreadSync();

        var loaded = await ChatService.GetMessagesAsync(channelId, 0, PageSize);
        messages = loaded;
        messageSkip = loaded.Count;
        hasMoreMessages = loaded.Count == PageSize;

        await BuildThreadReplyCounts();
        await ChatService.MarkChannelReadAsync(channelId);

        // Refresh channel list to clear unread badge
        channels = await ChatService.GetChannelsAsync();
    }

    private async Task LoadMoreMessages()
    {
        if (!hasMoreMessages || isLoadingMore || selectedChannelId is null) return;

        isLoadingMore = true;
        StateHasChanged();

        var older = await ChatService.GetMessagesAsync(selectedChannelId.Value, messageSkip, PageSize);
        messages.InsertRange(0, older);
        messageSkip += older.Count;
        hasMoreMessages = older.Count == PageSize;
        isLoadingMore = false;

        await BuildThreadReplyCounts();
    }

    private async Task SendMessage(string content)
    {
        if (selectedChannelId is null) return;
        var msg = await ChatService.SendMessageAsync(selectedChannelId.Value, content, null);
        messages.Add(msg);
    }

    private async Task OpenThread(int rootMessageId)
    {
        activeThreadRootId = rootMessageId;
        threadRootMessage = messages.FirstOrDefault(m => m.Id == rootMessageId);

        var thread = await ChatService.GetThreadAsync(rootMessageId);
        // Thread includes root message; replies exclude the root
        threadReplies = thread.Where(m => m.Id != rootMessageId).ToList();
    }

    private void CloseThread()
    {
        CloseThreadSync();
    }

    private void CloseThreadSync()
    {
        activeThreadRootId = null;
        threadRootMessage = null;
        threadReplies = [];
    }

    private async Task SendThreadReply(string content)
    {
        if (selectedChannelId is null || activeThreadRootId is null) return;

        var reply = await ChatService.SendMessageAsync(selectedChannelId.Value, content, activeThreadRootId.Value);
        threadReplies.Add(reply);

        // Update reply count for the root message
        threadReplyCounts[activeThreadRootId.Value] =
            threadReplyCounts.GetValueOrDefault(activeThreadRootId.Value) + 1;
    }

    private async Task HandleReaction((int MessageId, string Emoji) args)
    {
        await ChatService.AddReactionAsync(args.MessageId, args.Emoji);

        // Refresh the message to show updated reactions
        if (selectedChannelId is not null)
        {
            var refreshed = await ChatService.GetMessagesAsync(selectedChannelId.Value, 0, messages.Count);
            messages = refreshed;
        }
    }

    private async Task BuildThreadReplyCounts()
    {
        // Check each message to see if it has thread replies
        foreach (var msg in messages.Where(m => m.ReplyToId is null))
        {
            try
            {
                var thread = await ChatService.GetThreadAsync(msg.Id);
                var replyCount = thread.Count(t => t.Id != msg.Id);
                if (replyCount > 0)
                {
                    threadReplyCounts[msg.Id] = replyCount;
                }
            }
            catch
            {
                // Message may not be a thread root; ignore
            }
        }
    }
}

.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
}

.sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

.main-area {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    transition: flex 0.2s ease;
}

.main-area.with-thread {
    flex: 55;
}

.main-area.full-width {
    flex: 80;
}

.thread-pane {
    width: 25%;
    min-width: 280px;
    max-width: 400px;
    flex-shrink: 0;
}

.empty-state {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #616061;
    font-size: 1.1rem;
}

