.chat-layout {
    display: flex;
    height: 100vh;
    overflow: hidden;
}

.sidebar {
    width: 20%;
    min-width: 200px;
    max-width: 280px;
    flex-shrink: 0;
}

.main-area {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    transition: flex 0.2s ease;
}

.main-area.with-thread {
    flex: 55;
}

.main-area.full-width {
    flex: 80;
}

.thread-pane {
    width: 25%;
    min-width: 280px;
    max-width: 400px;
    flex-shrink: 0;
}

.empty-state {
    flex: 1;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #616061;
    font-size: 1.1rem;
}

